const MAX_RETRIES = 5;
let attempts = 0;
let retryTimer;
let stableTimer;
let socket;
let disposed = false;

function connect(url) {
  if (disposed) return;
  socket = new WebSocket(url);
  socket.addEventListener('open', () => {
    setStatus('online');
    stableTimer = window.setTimeout(() => { attempts = 0; }, 30_000);
  });
  socket.addEventListener('error', () => setStatus('error'));
  socket.addEventListener('close', (event) => {
    setStatus('offline');
    clearTimeout(stableTimer);
    if (disposed || event.code === 1000 || attempts >= MAX_RETRIES) return;
    const delay = Math.min(500 * 2 ** attempts, 15_000);
    attempts += 1;
    retryTimer = window.setTimeout(() => connect(url), delay + Math.random() * 250);
  });
}

function send(message) {
  if (socket?.readyState !== WebSocket.OPEN) return false;
  socket.send(JSON.stringify(message));
  return true;
}

function dispose() {
  disposed = true;
  clearTimeout(retryTimer);
  clearTimeout(stableTimer);
  socket?.close(1000, 'client disposed');
}

