const CACHE_PREFIX = 'study-shell-';
const CURRENT_CACHE = `${CACHE_PREFIX}v2`;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CURRENT_CACHE).then((cache) =>
      cache.addAll(['/', '/index.html', '/assets/app.css']),
    ),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    const outdated = names.filter(
      (name) => name.startsWith(CACHE_PREFIX) && name !== CURRENT_CACHE,
    );
    await Promise.all(outdated.map((name) => caches.delete(name)));
  })());
});

// Keep fetch handling scoped to eligible requests.
